type GuidanceReference = { id: string; messageKey: string };

function guidanceReferences(value: unknown): Record<string, GuidanceReference> | null {
  const raw = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const references: Record<string, GuidanceReference> = {};
  for (const [name, entry] of Object.entries(raw)) {
    if (!/^[A-Za-z][A-Za-z0-9_-]{0,127}$/.test(name) || !entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    const reference = entry as Partial<GuidanceReference>;
    if (typeof reference.id !== 'string' || typeof reference.messageKey !== 'string' || !/^[A-Za-z][A-Za-z0-9_.-]{0,127}$/.test(reference.id) || !/^[a-z][a-z0-9_.-]{0,127}$/.test(reference.messageKey)) return null;
    references[name] = { id: reference.id, messageKey: reference.messageKey };
  }
  return references;
}

