function translatedJsonGuidance(messages: Record<string, string>, reference: GuidanceReference | undefined, fallback: string): string {
  const value = translatedGuidance(messages, reference);
  if (!value) return fallback;
  try { JSON.parse(value); return value; } catch { return fallback; }
}

